// Format today's schedule
const events = items;

if (events.length === 0) {
  return [{
    json: {
      message: "📭 No events scheduled for today"
    }
  }];
}

let message = "📅 **Today's Schedule**\n";
message += new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
message += "\n\n";

for (const event of events) {
  const time = event.json.event_time ? event.json.event_time.substring(0, 5) : 'All day';
  const business = event.json.business_context || 'Personal';
  const businessEmoji = {
    'woodys_creations': '🎁',
    'dj_business': '🎵',
    'bmf_work': '💼',
    'pub': '🍺',
    'personal': '👤'
  }[business] || '📌';

  message += `${businessEmoji} **${time}** - ${business.replace('_', ' ').toUpperCase()}\n`;
  message += `   ${event.json.title}\n`;
  if (event.json.location) {
    message += `   📍 ${event.json.location}\n`;
  }
  if (event.json.notes) {
    message += `   📝 ${event.json.notes}\n`;
  }
  message += `\n`;
}

return [{
  json: {
    message: message,
    event_count: events.length
  }
}];

// Format week's events
const events = items;

if (events.length === 0) {
  return [{
    json: {
      message: "📭 No events scheduled this week"
    }
  }];
}

let message = "📅 **This Week's Events**\n\n";

// Group by date
const eventsByDate = {};

for (const event of events) {
  const date = event.json.event_date;
  if (!eventsByDate[date]) {
    eventsByDate[date] = [];
  }
  eventsByDate[date].push(event.json);
}

// Sort and format
const dates = Object.keys(eventsByDate).sort();

for (const date of dates) {
  const dateObj = new Date(date);
  const dateStr = dateObj.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });
  const isToday = date === new Date().toISOString().split('T')[0];

  message += isToday ? `**${dateStr} (TODAY)**\n` : `**${dateStr}**\n`;

  for (const event of eventsByDate[date]) {
    const time = event.event_time ? event.event_time.substring(0, 5) : 'All day';
    const business = event.business_context || 'Personal';
    const businessEmoji = {
      'woodys_creations': '🎁',
      'dj_business': '🎵',
      'bmf_work': '💼',
      'pub': '🍺',
      'personal': '👤'
    }[business] || '📌';

    message += `  ${time} ${businessEmoji} ${event.title}\n`;
  }
  message += `\n`;
}

message += `**Total: ${events.length} events**`;

return [{
  json: {
    message: message,
    event_count: events.length
  }
}];

// Parse event details
const input = items[0].json.message.text;
const lines = input.split('\n').map(l => l.trim()).filter(l => l);

if (lines.length < 4) {
  return [{
    json: {
      error: true,
      message: "❌ Missing required information (need at least title, date, time, business)"
    }
  }];
}

const title = lines[0];
const eventDate = lines[1];
const eventTime = lines[2].toLowerCase() === 'all-day' ? null : lines[2];
const business = lines[3].toLowerCase().replace(/\s+/g, '_');
const location = lines[4] || null;
const notes = lines[5] || null;

return [{
  json: {
    error: false,
    title: title,
    event_date: eventDate,
    event_time: eventTime,
    business_context: business,
    location: location,
    notes: notes,
    created_at: new Date().toISOString()
  }
}];

