// Format upcoming deadlines
const events = items;

if (events.length === 0) {
  return [{
    json: {
      message: "📭 No upcoming deadlines"
    }
  }];
}

let message = "⏰ **Upcoming Deadlines**\n\n";

for (const event of events) {
  const date = new Date(event.json.event_date);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const daysUntil = Math.ceil((date - today) / (1000 * 60 * 60 * 24));

  const dateStr = date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
  const business = event.json.business_context || 'Unknown';
  const businessEmoji = {
    'woodys_creations': '🎁',
    'dj_business': '🎵',
    'bmf_work': '💼',
    'pub': '🍺'
  }[business] || '📌';

  // Urgency indicator
  const urgency = daysUntil <= 1 ? '🔴' : daysUntil <= 3 ? '🟡' : '🟢';

  message += `${urgency} ${businessEmoji} **${event.json.title}**\n`;
  message += `   📅 ${dateStr} (${daysUntil} days)\n`;
  if (event.json.notes) {
    message += `   📝 ${event.json.notes}\n`;
  }
  message += `\n`;
}

return [{
  json: {
    message: message,
    deadline_count: events.length
  }
}];
